                "pool": {
                    "type": "string"
                },
                "pool_slots": {
                    "type": "number"
                },
                "priority_weight": {
                    "type": "number"
                },
                "queue": {
                    "type": "string"
                },
                "retries": {
                    "type": "number"
                },
                "retry_delay": {
                    "$ref": "#/definitions/timedelta"
                },
                "retry_exponential_backoff": {
                    "type": "boolean"
                },
                "start_date": {
                    "$ref": "#/definitions/datetime"
                },
                "subdag": {
                    "$ref": "#/definitions/dag"
                },
                "task_id": {
                    "type": "string"
                },
                "template_fields": {
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                },
                "trigger_rule": {
                    "type": "string"
                },
                "ui_color": {
                    "$ref": "#/definitions/color"
                },
                "ui_fgcolor": {
                    "$ref": "#/definitions/color"
