                "_task_type",
                "_task_module",
                "task_id",
                "ui_color",
                "ui_fgcolor",
                "template_fields"
            ],
            "type": "object"
        },
        "tasks": {
            "additionalProperties": {
                "$ref": "#/definitions/operator"
            },
            "type": "array"
        },
        "timedelta": {
            "minimum": 0,
            "type": "number"
        },
        "timezone": {
            "type": "string"
        },
        "typed_relativedelta": {
            "description": "A dateutil.relativedelta.relativedelta object",
            "properties": {
                "__type": {
                    "const": "relativedelta",
                    "type": "string"
                },
                "__var": {
                    "additionalProperties": {
                        "type": "integer"
                    },
                    "properties": {
                        "weekday": {
                            "items": {
                                "type": "integer"
                            },
                            "maxItems": 2,
                            "minItems": 1,
                            "type": "array"
                        }
                    },
                    "type": "object"
                }
            },
            "type": "object"
        },
        "typed_timedelta": {
            "additionalProperties": false,
            "properties": {
                "__type": {
                    "const": "timedelta",
                    "type": "string"
                },
                "__var": {
                    "$ref": "#/definitions/timedelta"
                }
            },
            "required": [
                "__type",
                "__var"
            ],
            "type": "object"
        }
    },
    "type": "object"
}

